INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','agreement-advanced','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"agreement-advanced","title":"Agreement with complex subjects","level":"B2","order":58,"summary":"Find the head of a subject phrase and handle indefinite pronouns, quantities and collective nouns carefully.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["The head controls agreement","Indefinite pronouns","Coordinated subjects and quantities","Collective nouns and variation"],"rules":[{"title":"The head controls agreement","explanation":"A subject can contain another noun inside a prepositional phrase. In ordinary agreement, the **head of the subject phrase** controls the verb, not the nearest noun. The box of tools is singular because box is the head.","pattern":"The **list** of names **is** ready.","commonMistakes":["The list of names are ready incorrectly lets the nearby plural names control agreement."],"examples":["“The list of tasks needed to prepare the visitor guide **is** ready.”","“The list of tasks needed to restore the old portrait **is** ready.”"],"skill":"form"},{"title":"Indefinite pronouns","explanation":"Everyone, someone, anybody and each normally take singular verb agreement. They can still be referred back to with singular they. Each of the students is ready combines singular each with a plural noun inside an of phrase.","pattern":"**Everyone is** ready; **they** have a ticket.","commonMistakes":["Singular they does not change the agreement of everyone itself to plural."],"examples":["“Everyone who can prepare the visitor guide **is** welcome.”","“Everyone who can restore the old portrait **is** welcome.”"],"skill":"meaning"},{"title":"Coordinated subjects and quantities","explanation":"Two separate subjects joined by and normally take a plural verb. A combined dish, title or single measured amount can be treated as one unit. Percentages and fractions often take agreement from what is being measured.","pattern":"The guide and the driver **are** here. / Ten pounds **is** enough.","commonMistakes":["Agreement with quantities depends on meaning: ten pounds is a price, but the coins are separate objects."],"examples":["“The guide and the assistant **are** ready to prepare the visitor guide.”","“The guide and the assistant **are** ready to restore the old portrait.”"],"skill":"contrast"},{"title":"Collective nouns and variation","explanation":"A team or committee may take singular agreement when treated as one unit. British English also commonly uses plural agreement when its members are in focus; American English more often favours singular. Keep pronoun choices and viewpoint consistent.","pattern":"The team **is** united. / The team **are** arguing among themselves.","commonMistakes":["Do not label every plural collective agreement wrong without specifying variety and intended meaning."],"examples":["“Each of the people assigned to prepare the visitor guide **has** a copy of the instructions.”","“Each of the people assigned to restore the old portrait **has** a copy of the instructions.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-agreement","dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Find the head of a subject phrase and handle indefinite pronouns, quantities and collective nouns carefully.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"The head controls agreement","explanation":"A subject can contain another noun inside a prepositional phrase. In ordinary agreement, the **head of the subject phrase** controls the verb, not the nearest noun. The box of tools is singular because box is the head.","pattern":"The **list** of names **is** ready.","commonMistakes":["The list of names are ready incorrectly lets the nearby plural names control agreement."],"examples":["“The list of tasks needed to prepare the visitor guide **is** ready.”","“The list of tasks needed to restore the old portrait **is** ready.”"],"skill":"form","id":"agreement-advanced-foundation-1","domain":"clause-patterns","referenceIds":["bc-agreement","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Indefinite pronouns","explanation":"Everyone, someone, anybody and each normally take singular verb agreement. They can still be referred back to with singular they. Each of the students is ready combines singular each with a plural noun inside an of phrase.","pattern":"**Everyone is** ready; **they** have a ticket.","commonMistakes":["Singular they does not change the agreement of everyone itself to plural."],"examples":["“Everyone who can prepare the visitor guide **is** welcome.”","“Everyone who can restore the old portrait **is** welcome.”"],"skill":"meaning","id":"agreement-advanced-foundation-2","domain":"clause-patterns","referenceIds":["bc-agreement","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Coordinated subjects and quantities","explanation":"Two separate subjects joined by and normally take a plural verb. A combined dish, title or single measured amount can be treated as one unit. Percentages and fractions often take agreement from what is being measured.","pattern":"The guide and the driver **are** here. / Ten pounds **is** enough.","commonMistakes":["Agreement with quantities depends on meaning: ten pounds is a price, but the coins are separate objects."],"examples":["“The guide and the assistant **are** ready to prepare the visitor guide.”","“The guide and the assistant **are** ready to restore the old portrait.”"],"skill":"contrast","id":"agreement-advanced-foundation-3","domain":"clause-patterns","referenceIds":["bc-agreement","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Collective nouns and variation","explanation":"A team or committee may take singular agreement when treated as one unit. British English also commonly uses plural agreement when its members are in focus; American English more often favours singular. Keep pronoun choices and viewpoint consistent.","pattern":"The team **is** united. / The team **are** arguing among themselves.","commonMistakes":["Do not label every plural collective agreement wrong without specifying variety and intended meaning."],"examples":["“Each of the people assigned to prepare the visitor guide **has** a copy of the instructions.”","“Each of the people assigned to restore the old portrait **has** a copy of the instructions.”"],"skill":"application","id":"agreement-advanced-foundation-4","domain":"clause-patterns","referenceIds":["bc-agreement","dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"domain":"clause-patterns","id":"notional-proximity-agreement","title":"Grammatical, notional and proximity agreement","explanation":"Agreement usually follows the grammatical head, but meaning and nearby alternatives also influence established patterns. A collective noun can be singular as a unit or plural as members, especially in British English. A sum or measurement can be treated as one amount. Rephrase mixed-number alternatives when agreement becomes distracting.","pattern":"**Ten pounds is** enough.","examples":["**The team is** winning. / **The team are** arguing among themselves.","**A number of people are** waiting; **the number is** increasing."],"commonMistakes":["A plural noun inside an of-phrase does not normally control agreement with a singular head: the quality of the reports is high."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"clause-patterns","id":"agreement-special-subjects","title":"Subjects that are clauses, titles and coordinated ideas","explanation":"A clause used as a subject generally takes singular agreement. A title can denote one work even when its words look plural. Coordinated nouns normally take plural agreement, but a conventional pairing or one combined concept can be treated as singular. Meaning and established usage must be read alongside the visible word forms.","pattern":"**What she said was** helpful.","examples":["**Reading before bed helps** me relax.","**Bread and butter is** all we have for breakfast."],"commonMistakes":["A fused relative with plural interpretation may allow plural agreement in some patterns: What we need are more chairs. Avoid reducing all what-clause agreement to one mechanical rule."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["The **list** of names **is** ready.","**Everyone is** ready; **they** have a ticket.","The guide and the driver **are** here. / Ten pounds **is** enough.","The team **is** united. / The team **are** arguing among themselves."],"readingVersion":"core-2026-09-v4"},"stage":"5 · Complex sentences","prerequisites":["punctuation-clauses"],"readingReferenceIds":["bc-agreement","dfe-grammar","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='agreement-advanced'
